class MicroVMError(Exception):
    """Base class for all MicroVM errors."""


class LexError(MicroVMError):
    def __init__(self, message: str, offset: int) -> None:
        super().__init__(message)
        self.offset: int = offset


class ParseError(MicroVMError):
    def __init__(self, message: str, offset: int) -> None:
        super().__init__(message)
        self.offset: int = offset


class CompileError(MicroVMError):
    pass


class SerializationError(MicroVMError):
    pass


class VMRuntimeError(MicroVMError):
    pass


class StepLimitError(VMRuntimeError):
    pass

OPCODES: tuple[str, ...] = (
    "CONST", "LOAD", "STORE", "ADD", "SUB", "MUL", "DIV", "MOD", "NEG", "NOT",
    "EQ", "NE", "LT", "LE", "GT", "GE", "JUMP", "JUMP_IF_FALSE", "PRINT", "POP",
    "HALT",
)
OPCODE_NUMBERS: dict[str, int] = {name: index + 1 for index, name in enumerate(OPCODES)}
ARG_OPCODE_NAMES: set[str] = {"CONST", "LOAD", "STORE", "JUMP", "JUMP_IF_FALSE"}

import dataclasses

from .errors import ParseError
from .lexer import Token


@dataclasses.dataclass(frozen=True)
class Literal:
    value: object


@dataclasses.dataclass(frozen=True)
class Name:
    name: str


@dataclasses.dataclass(frozen=True)
class Unary:
    op: str
    operand: object


@dataclasses.dataclass(frozen=True)
class Binary:
    op: str
    left: object
    right: object


@dataclasses.dataclass(frozen=True)
class LetStmt:
    name: str
    value: object


@dataclasses.dataclass(frozen=True)
class AssignStmt:
    name: str
    value: object


@dataclasses.dataclass(frozen=True)
class PrintStmt:
    value: object


@dataclasses.dataclass(frozen=True)
class IfStmt:
    condition: object
    then_branch: object
    else_branch: object | None


@dataclasses.dataclass(frozen=True)
class WhileStmt:
    condition: object
    body: object


@dataclasses.dataclass(frozen=True)
class BlockStmt:
    statements: list[object]


class Parser:
    def __init__(self, tokens: list[Token]) -> None:
        self.tokens = tokens
        self.index = 0

    def peek(self) -> Token | None:
        if self.index >= len(self.tokens):
            return None
        return self.tokens[self.index]

    def advance(self) -> Token:
        token = self.peek()
        if token is None:
            raise ParseError("Unexpected end of input", 0)
        self.index += 1
        return token

    def match(self, kind: str, text: str | None = None) -> Token | None:
        token = self.peek()
        if token is None:
            return None
        if token.kind != kind:
            return None
        if text is not None and token.text != text:
            return None
        self.index += 1
        return token

    def expect(self, kind: str, text: str | None = None) -> Token:
        token = self.peek()
        if token is None:
            raise ParseError("Unexpected end of input", 0)
        if token.kind != kind or (text is not None and token.text != text):
            raise ParseError(f"Expected {text or kind}", token.offset)
        self.index += 1
        return token

    def parse_program(self) -> list[object]:
        statements: list[object] = []
        while self.peek() is not None:
            statements.append(self.parse_statement())
        return statements

    def parse_statement(self) -> object:
        token = self.peek()
        if token is None:
            raise ParseError("Unexpected end of input", 0)
        if token.kind == "KEYWORD" and token.text == "let":
            return self.parse_let()
        if token.kind == "KEYWORD" and token.text == "print":
            return self.parse_print()
        if token.kind == "KEYWORD" and token.text == "if":
            return self.parse_if()
        if token.kind == "KEYWORD" and token.text == "while":
            return self.parse_while()
        if token.kind == "OP" and token.text == "{":
            return self.parse_block()
        if token.kind == "IDENT":
            return self.parse_assignment()
        raise ParseError(f"Unexpected token {token.text!r}", token.offset)

    def parse_block(self) -> BlockStmt:
        self.expect("OP", "{")
        statements: list[object] = []
        while self.peek() is not None and not (self.peek().kind == "OP" and self.peek().text == "}"):
            statements.append(self.parse_statement())
        self.expect("OP", "}")
        return BlockStmt(statements)

    def parse_let(self) -> LetStmt:
        self.expect("KEYWORD", "let")
        name = self.expect("IDENT").text
        self.expect("OP", "=")
        value = self.parse_expression()
        self.expect("OP", ";")
        return LetStmt(name, value)

    def parse_assignment(self) -> AssignStmt:
        name = self.expect("IDENT").text
        self.expect("OP", "=")
        value = self.parse_expression()
        self.expect("OP", ";")
        return AssignStmt(name, value)

    def parse_print(self) -> PrintStmt:
        self.expect("KEYWORD", "print")
        value = self.parse_expression()
        self.expect("OP", ";")
        return PrintStmt(value)

    def parse_if(self) -> IfStmt:
        self.expect("KEYWORD", "if")
        self.expect("OP", "(")
        condition = self.parse_expression()
        self.expect("OP", ")")
        then_branch = self.parse_statement()
        else_branch: object | None = None
        if self.peek() is not None and self.peek().kind == "KEYWORD" and self.peek().text == "else":
            self.advance()
            if self.peek() is not None and self.peek().kind == "KEYWORD" and self.peek().text == "if":
                else_branch = self.parse_if()
            else:
                else_branch = self.parse_statement()
        return IfStmt(condition, then_branch, else_branch)

    def parse_while(self) -> WhileStmt:
        self.expect("KEYWORD", "while")
        self.expect("OP", "(")
        condition = self.parse_expression()
        self.expect("OP", ")")
        body = self.parse_statement()
        return WhileStmt(condition, body)

    def parse_expression(self) -> object:
        return self.parse_or()

    def parse_or(self) -> object:
        node = self.parse_and()
        while self.peek() is not None and self.peek().kind == "KEYWORD" and self.peek().text == "or":
            self.advance()
            node = Binary("or", node, self.parse_and())
        return node

    def parse_and(self) -> object:
        node = self.parse_not()
        while self.peek() is not None and self.peek().kind == "KEYWORD" and self.peek().text == "and":
            self.advance()
            node = Binary("and", node, self.parse_not())
        return node

    def parse_not(self) -> object:
        if self.peek() is not None and self.peek().kind == "KEYWORD" and self.peek().text == "not":
            self.advance()
            return Unary("not", self.parse_not())
        return self.parse_comparison()

    def parse_comparison(self) -> object:
        node = self.parse_additive()
        if self.peek() is not None and self.peek().kind == "OP" and self.peek().text in {"==", "!=", "<", "<=", ">", ">="}:
            op = self.advance().text
            right = self.parse_additive()
            if self.peek() is not None and self.peek().kind == "OP" and self.peek().text in {"==", "!=", "<", "<=", ">", ">="}:
                raise ParseError("Chained comparison is not allowed", self.peek().offset)
            return Binary(op, node, right)
        return node

    def parse_additive(self) -> object:
        node = self.parse_multiplicative()
        while self.peek() is not None and self.peek().kind == "OP" and self.peek().text in {"+", "-"}:
            op = self.advance().text
            node = Binary(op, node, self.parse_multiplicative())
        return node

    def parse_multiplicative(self) -> object:
        node = self.parse_unary()
        while self.peek() is not None and self.peek().kind == "OP" and self.peek().text in {"*", "/", "%"}:
            op = self.advance().text
            node = Binary(op, node, self.parse_unary())
        return node

    def parse_unary(self) -> object:
        if self.peek() is not None and self.peek().kind == "OP" and self.peek().text == "-":
            self.advance()
            return Unary("neg", self.parse_unary())
        return self.parse_primary()

    def parse_primary(self) -> object:
        token = self.peek()
        if token is None:
            raise ParseError("Unexpected end of input", 0)
        if token.kind == "INT":
            self.advance()
            return Literal(token.value)
        if token.kind == "FLOAT":
            self.advance()
            return Literal(token.value)
        if token.kind == "STRING":
            self.advance()
            return Literal(token.value)
        if token.kind == "KEYWORD" and token.text in {"true", "false"}:
            self.advance()
            return Literal(token.text == "true")
        if token.kind == "IDENT":
            self.advance()
            return Name(token.text)
        if token.kind == "OP" and token.text == "(":
            self.advance()
            expr = self.parse_expression()
            self.expect("OP", ")")
            return expr
        raise ParseError(f"Unexpected token {token.text!r}", token.offset)


def parse(src: str) -> list[object]:
    tokens = []
    from .lexer import tokenize

    tokens = tokenize(src)
    parser = Parser(tokens)
    return parser.parse_program()

from .parser import (
    AssignStmt,
    Binary,
    BlockStmt,
    IfStmt,
    LetStmt,
    Literal,
    Name,
    PrintStmt,
    Unary,
    WhileStmt,
)


_NO_RESULT = object()


def _is_bool(value: object) -> bool:
    return type(value) is bool


def _is_number(value: object) -> bool:
    return type(value) in (int, float) and not _is_bool(value)


def _binary_ok(op: str, left: object, right: object) -> object:
    if op == "+":
        if type(left) is str and type(right) is str:
            return left + right
        if _is_number(left) and _is_number(right):
            if type(left) is float or type(right) is float:
                return float(left) + float(right)
            return left + right
        return _NO_RESULT
    if op == "-":
        if _is_number(left) and _is_number(right):
            if type(left) is float or type(right) is float:
                return float(left) - float(right)
            return left - right
        return _NO_RESULT
    if op == "*":
        if _is_number(left) and _is_number(right):
            if type(left) is float or type(right) is float:
                return float(left) * float(right)
            return left * right
        return _NO_RESULT
    if op == "/":
        if _is_number(left) and _is_number(right):
            if right == 0:
                return _NO_RESULT
            return float(left) / float(right)
        return _NO_RESULT
    if op == "%":
        if type(left) is int and type(right) is int:
            if right == 0:
                return _NO_RESULT
            return left % right
        return _NO_RESULT
    if op == "==":
        if type(left) is bool or type(right) is bool:
            if type(left) is bool and type(right) is bool:
                return left == right
            return False
        if _is_number(left) and _is_number(right):
            return float(left) == float(right)
        if type(left) is str and type(right) is str:
            return left == right
        return False
    if op == "!=":
        if type(left) is bool or type(right) is bool:
            if type(left) is bool and type(right) is bool:
                return left != right
            return True
        if _is_number(left) and _is_number(right):
            return float(left) != float(right)
        if type(left) is str and type(right) is str:
            return left != right
        return True
    if op in {"<", "<=", ">", ">="}:
        if _is_number(left) and _is_number(right):
            if op == "<":
                return float(left) < float(right)
            if op == "<=":
                return float(left) <= float(right)
            if op == ">":
                return float(left) > float(right)
            return float(left) >= float(right)
        if type(left) is str and type(right) is str:
            if op == "<":
                return left < right
            if op == "<=":
                return left <= right
            if op == ">":
                return left > right
            return left >= right
        return _NO_RESULT
    return _NO_RESULT


def _unary_ok(op: str, value: object) -> object:
    if op == "neg":
        if _is_number(value):
            return -value
        return _NO_RESULT
    if op == "not":
        if _is_bool(value):
            return not value
        return _NO_RESULT
    return _NO_RESULT


def _fold_logic(op: str, left: object, right: object) -> object:
    if op == "and":
        if isinstance(left, Literal) and _is_bool(left.value):
            if left.value is False:
                return Literal(False)
        if isinstance(right, Literal) and _is_bool(right.value):
            if right.value is False:
                return Literal(False)
        if isinstance(left, Literal) and _is_bool(left.value) and isinstance(right, Literal) and _is_bool(right.value):
            return Literal(left.value and right.value)
    if op == "or":
        if isinstance(left, Literal) and _is_bool(left.value):
            if left.value is True:
                return Literal(True)
        if isinstance(right, Literal) and _is_bool(right.value):
            if right.value is True:
                return Literal(True)
        if isinstance(left, Literal) and _is_bool(left.value) and isinstance(right, Literal) and _is_bool(right.value):
            return Literal(left.value or right.value)
    return _NO_RESULT


def fold_constants(node: object) -> object:
    if isinstance(node, list):
        return [fold_constants(item) for item in node]
    if isinstance(node, Literal):
        return node
    if isinstance(node, Name):
        return node
    if isinstance(node, Unary):
        operand = fold_constants(node.operand)
        if isinstance(operand, Literal):
            folded = _unary_ok(node.op, operand.value)
            if folded is not _NO_RESULT:
                return Literal(folded)
        return Unary(node.op, operand)
    if isinstance(node, Binary):
        left = fold_constants(node.left)
        right = fold_constants(node.right)
        if node.op in {"and", "or"}:
            folded = _fold_logic(node.op, left, right)
            if folded is not _NO_RESULT:
                return folded
        if isinstance(left, Literal) and isinstance(right, Literal):
            folded = _binary_ok(node.op, left.value, right.value)
            if folded is not _NO_RESULT:
                return Literal(folded)
        return Binary(node.op, left, right)
    if isinstance(node, LetStmt):
        return LetStmt(node.name, fold_constants(node.value))
    if isinstance(node, AssignStmt):
        return AssignStmt(node.name, fold_constants(node.value))
    if isinstance(node, PrintStmt):
        return PrintStmt(fold_constants(node.value))
    if isinstance(node, BlockStmt):
        return BlockStmt([fold_constants(item) for item in node.statements])
    if isinstance(node, IfStmt):
        return IfStmt(fold_constants(node.condition), fold_constants(node.then_branch), fold_constants(node.else_branch) if node.else_branch is not None else None)
    if isinstance(node, WhileStmt):
        return WhileStmt(fold_constants(node.condition), fold_constants(node.body))
    return node

from .compiler import Instr, Program
from .errors import StepLimitError, VMRuntimeError

_MISSING = object()


def _render_value(value: object) -> str:
    if type(value) is bool:
        return "true" if value else "false"
    return str(value)


def _is_number(value: object) -> bool:
    return type(value) in (int, float) and type(value) is not bool


def _pop_two(stack: list[object]) -> tuple[object, object]:
    right = stack.pop()
    left = stack.pop()
    return left, right


def _bin_add(left: object, right: object) -> object:
    if type(left) is str and type(right) is str:
        return left + right
    if _is_number(left) and _is_number(right):
        if type(left) is float or type(right) is float:
            return float(left) + float(right)
        return int(left) + int(right)
    raise VMRuntimeError("Invalid operands for +")


def _bin_sub(left: object, right: object) -> object:
    if _is_number(left) and _is_number(right):
        if type(left) is float or type(right) is float:
            return float(left) - float(right)
        return int(left) - int(right)
    raise VMRuntimeError("Invalid operands for -")


def _bin_mul(left: object, right: object) -> object:
    if _is_number(left) and _is_number(right):
        if type(left) is float or type(right) is float:
            return float(left) * float(right)
        return int(left) * int(right)
    raise VMRuntimeError("Invalid operands for *")


def _bin_div(left: object, right: object) -> object:
    if _is_number(left) and _is_number(right):
        if right == 0:
            raise VMRuntimeError("Division by zero")
        return float(left) / float(right)
    raise VMRuntimeError("Invalid operands for /")


def _bin_mod(left: object, right: object) -> object:
    if type(left) is int and type(right) is int:
        if right == 0:
            raise VMRuntimeError("Modulo by zero")
        return left % right
    raise VMRuntimeError("Invalid operands for %")


def _cmp_values(op: str, left: object, right: object) -> bool:
    if _is_number(left) and _is_number(right):
        a = float(left)
        b = float(right)
        if op == "<":
            return a < b
        if op == "<=":
            return a <= b
        if op == ">":
            return a > b
        return a >= b
    if type(left) is str and type(right) is str:
        if op == "<":
            return left < right
        if op == "<=":
            return left <= right
        if op == ">":
            return left > right
        return left >= right
    raise VMRuntimeError("Invalid comparison operands")


def _eq_values(left: object, right: object) -> bool:
    if type(left) is bool or type(right) is bool:
        if type(left) is bool and type(right) is bool:
            return left == right
        return False
    if _is_number(left) and _is_number(right):
        return float(left) == float(right)
    if type(left) is str and type(right) is str:
        return left == right
    return left == right


def _ne_values(left: object, right: object) -> bool:
    return not _eq_values(left, right)


def _apply_binary(opcode: str, left: object, right: object) -> object:
    if opcode == "ADD":
        return _bin_add(left, right)
    if opcode == "SUB":
        return _bin_sub(left, right)
    if opcode == "MUL":
        return _bin_mul(left, right)
    if opcode == "DIV":
        return _bin_div(left, right)
    if opcode == "MOD":
        return _bin_mod(left, right)
    if opcode == "EQ":
        return _eq_values(left, right)
    if opcode == "NE":
        return _ne_values(left, right)
    if opcode in {"LT", "LE", "GT", "GE"}:
        return _cmp_values(opcode[1:] if opcode.startswith("L") else opcode[0], left, right) if False else _cmp_values({"LT": "<", "LE": "<=", "GT": ">", "GE": ">="}[opcode], left, right)
    raise VMRuntimeError(f"Unsupported binary opcode: {opcode}")


def execute(program: Program, *, step_limit: int = 100_000) -> list[str]:
    if type(step_limit) is not int or step_limit <= 0:
        raise ValueError("step_limit must be a positive int")
    stack: list[object] = []
    memory: list[object] = [_MISSING for _ in program.names]
    outputs: list[str] = []
    ip = 0
    steps = 0
    while ip < len(program.instructions):
        instr = program.instructions[ip]
        steps += 1
        if steps > step_limit:
            raise StepLimitError("Step limit exceeded")
        op = instr.op
        if op == "CONST":
            stack.append(program.constants[instr.arg])
        elif op == "LOAD":
            value = memory[instr.arg]
            if value is _MISSING:
                raise VMRuntimeError(f"Variable '{program.names[instr.arg]}' is not assigned")
            stack.append(value)
        elif op == "STORE":
            memory[instr.arg] = stack.pop()
        elif op == "ADD":
            left, right = _pop_two(stack)
            stack.append(_bin_add(left, right))
        elif op == "SUB":
            left, right = _pop_two(stack)
            stack.append(_bin_sub(left, right))
        elif op == "MUL":
            left, right = _pop_two(stack)
            stack.append(_bin_mul(left, right))
        elif op == "DIV":
            left, right = _pop_two(stack)
            stack.append(_bin_div(left, right))
        elif op == "MOD":
            left, right = _pop_two(stack)
            stack.append(_bin_mod(left, right))
        elif op == "NEG":
            value = stack.pop()
            if not _is_number(value):
                raise VMRuntimeError("Unary - requires a number")
            stack.append(-value)
        elif op == "NOT":
            value = stack.pop()
            if type(value) is not bool:
                raise VMRuntimeError("NOT requires a bool")
            stack.append(not value)
        elif op == "EQ":
            left, right = _pop_two(stack)
            stack.append(_eq_values(left, right))
        elif op == "NE":
            left, right = _pop_two(stack)
            stack.append(_ne_values(left, right))
        elif op == "LT":
            left, right = _pop_two(stack)
            stack.append(_cmp_values("<", left, right))
        elif op == "LE":
            left, right = _pop_two(stack)
            stack.append(_cmp_values("<=", left, right))
        elif op == "GT":
            left, right = _pop_two(stack)
            stack.append(_cmp_values(">", left, right))
        elif op == "GE":
            left, right = _pop_two(stack)
            stack.append(_cmp_values(">=", left, right))
        elif op == "JUMP":
            ip = instr.arg
            continue
        elif op == "JUMP_IF_FALSE":
            value = stack.pop()
            if type(value) is not bool:
                raise VMRuntimeError("Condition must be bool")
            if not value:
                ip = instr.arg
                continue
        elif op == "PRINT":
            value = stack.pop()
            outputs.append(_render_value(value))
        elif op == "POP":
            stack.pop()
        elif op == "HALT":
            break
        ip += 1
    return outputs

import struct
import zlib

from .compiler import Program
from .errors import SerializationError
from .opcodes import ARG_OPCODE_NAMES, OPCODE_NUMBERS


def _int64_payload(value: int) -> bytes:
    if value < -(1 << 63) or value > (1 << 63) - 1:
        raise SerializationError("INT constant out of range")
    return value.to_bytes(8, byteorder="big", signed=True)


def _encode_constant(value: object) -> tuple[int, bytes]:
    if type(value) is int:
        return 0x01, _int64_payload(value)
    if type(value) is float:
        return 0x02, struct.pack(">d", value)
    if type(value) is str:
        encoded = value.encode("utf-8")
        return 0x03, len(encoded).to_bytes(4, byteorder="big") + encoded
    if type(value) is bool:
        return 0x04, b"\x01" if value else b"\x00"
    raise SerializationError(f"Unsupported constant type: {type(value).__name__}")


def _decode_constant(tag: int, payload: bytes) -> object:
    if tag == 0x01:
        if len(payload) != 8:
            raise SerializationError("Truncated INT payload")
        return int.from_bytes(payload, byteorder="big", signed=True)
    if tag == 0x02:
        if len(payload) != 8:
            raise SerializationError("Truncated FLOAT payload")
        return struct.unpack(">d", payload)[0]
    if tag == 0x03:
        if len(payload) < 4:
            raise SerializationError("Truncated STRING payload")
        length = int.from_bytes(payload[:4], byteorder="big")
        if len(payload) != 4 + length:
            raise SerializationError("Truncated STRING payload")
        return payload[4:].decode("utf-8")
    if tag == 0x04:
        if len(payload) != 1:
            raise SerializationError("Truncated BOOL payload")
        value = payload[0]
        if value not in (0, 1):
            raise SerializationError("BOOL payload must be 0 or 1")
        return value == 1
    raise SerializationError(f"Unknown constant tag: {tag:#x}")


def _encode_name(name: str) -> bytes:
    data = name.encode("utf-8")
    return len(data).to_bytes(2, byteorder="big") + data


def dumps(program: Program) -> bytes:
    body = bytearray()
    body.extend(b"MVM1")
    body.append(1)
    body.extend(len(program.names).to_bytes(2, byteorder="big"))
    for name in program.names:
        body.extend(_encode_name(name))
    body.extend(len(program.constants).to_bytes(2, byteorder="big"))
    for constant in program.constants:
        tag, payload = _encode_constant(constant)
        body.append(tag)
        body.extend(payload)
    body.extend(len(program.instructions).to_bytes(4, byteorder="big"))
    for instr in program.instructions:
        code = OPCODE_NUMBERS[instr.op]
        body.append(code)
        if instr.op in ARG_OPCODE_NAMES:
            if instr.arg is None:
                raise SerializationError(f"Missing arg for {instr.op}")
            body.extend(int(instr.arg).to_bytes(4, byteorder="big"))
        else:
            body.extend((0xFFFFFFFF).to_bytes(4, byteorder="big"))
    checksum = zlib.crc32(body[4:]) & 0xFFFFFFFF
    return b"MVM1" + body[4:] + checksum.to_bytes(4, byteorder="big")


def loads(data: bytes) -> Program:
    if not isinstance(data, (bytes, bytearray)):
        raise SerializationError("Input must be bytes")
    blob = bytes(data)
    if len(blob) < 17:
        raise SerializationError("Truncated data")
    if blob[:4] != b"MVM1":
        raise SerializationError("Bad magic")
    if blob[4] != 1:
        raise SerializationError("Unsupported version")
    checksum = int.from_bytes(blob[-4:], byteorder="big")
    payload = blob[4:-4]
    if zlib.crc32(payload) & 0xFFFFFFFF != checksum:
        raise SerializationError("Checksum mismatch")
    pos = 0
    version = payload[pos]
    pos += 1
    if version != 1:
        raise SerializationError("Unsupported version")
    if pos + 2 > len(payload):
        raise SerializationError("Truncated name count")
    name_count = int.from_bytes(payload[pos:pos + 2], byteorder="big")
    pos += 2
    names: list[str] = []
    for _ in range(name_count):
        if pos + 2 > len(payload):
            raise SerializationError("Truncated name length")
        length = int.from_bytes(payload[pos:pos + 2], byteorder="big")
        pos += 2
        if pos + length > len(payload):
            raise SerializationError("Truncated name data")
        names.append(payload[pos:pos + length].decode("utf-8"))
        pos += length
    if pos + 2 > len(payload):
        raise SerializationError("Truncated constant count")
    const_count = int.from_bytes(payload[pos:pos + 2], byteorder="big")
    pos += 2
    constants: list[object] = []
    for _ in range(const_count):
        if pos >= len(payload):
            raise SerializationError("Truncated constant tag")
        tag = payload[pos]
        pos += 1
        if tag == 0x01:
            if pos + 8 > len(payload):
                raise SerializationError("Truncated integer constant")
            constant = int.from_bytes(payload[pos:pos + 8], byteorder="big", signed=True)
            pos += 8
        elif tag == 0x02:
            if pos + 8 > len(payload):
                raise SerializationError("Truncated float constant")
            constant = struct.unpack(">d", payload[pos:pos + 8])[0]
            pos += 8
        elif tag == 0x03:
            if pos + 4 > len(payload):
                raise SerializationError("Truncated string length")
            length = int.from_bytes(payload[pos:pos + 4], byteorder="big")
            pos += 4
            if pos + length > len(payload):
                raise SerializationError("Truncated string data")
            constant = payload[pos:pos + length].decode("utf-8")
            pos += length
        elif tag == 0x04:
            if pos >= len(payload):
                raise SerializationError("Truncated bool constant")
            value = payload[pos]
            if value not in (0, 1):
                raise SerializationError("BOOL constant payload must be 0 or 1")
            constant = value == 1
            pos += 1
        else:
            raise SerializationError(f"Unknown constant tag: {tag:#x}")
        constants.append(constant)
    if pos + 4 > len(payload):
        raise SerializationError("Truncated instruction count")
    instr_count = int.from_bytes(payload[pos:pos + 4], byteorder="big")
    pos += 4
    instructions = []
    for _ in range(instr_count):
        if pos >= len(payload):
            raise SerializationError("Truncated opcode")
        opcode_num = payload[pos]
        pos += 1
        reverse = {value: key for key, value in OPCODE_NUMBERS.items()}
        if opcode_num not in reverse:
            raise SerializationError(f"Unknown opcode number: {opcode_num}")
        opcode = reverse[opcode_num]
        if pos + 4 > len(payload):
            raise SerializationError("Truncated instruction argument")
        arg_value = int.from_bytes(payload[pos:pos + 4], byteorder="big")
        pos += 4
        if opcode in ARG_OPCODE_NAMES:
            if arg_value == 0xFFFFFFFF:
                raise SerializationError(f"Missing argument for {opcode}")
            arg = int(arg_value)
        else:
            if arg_value != 0xFFFFFFFF:
                raise SerializationError(f"Unexpected argument for {opcode}")
            arg = None
        instructions.append(__import__("microvm.compiler", fromlist=["Instr"]).Instr(opcode, arg))
    if pos != len(payload):
        raise SerializationError("Trailing bytes after checksum")
    return Program(constants, names, instructions)

from .compiler import Program
from .opcodes import ARG_OPCODE_NAMES


def _escape_string(value: str) -> str:
    return '"' + value.replace("\\", "\\\\").replace('"', '\\"').replace("\n", "\\n").replace("\t", "\\t") + '"'


def disassemble(program: Program) -> str:
    lines: list[str] = []
    for index, instr in enumerate(program.instructions):
        if instr.arg is None:
            lines.append(f"{index:04d} {instr.op}")
            continue
        line = f"{index:04d} {instr.op} {instr.arg}"
        if instr.op == "CONST":
            value = program.constants[instr.arg]
            if type(value) is bool:
                rendered = "true" if value else "false"
            elif type(value) is str:
                rendered = _escape_string(value)
            else:
                rendered = str(value)
            line += f"  ; {rendered}"
        lines.append(line)
    return "\n".join(lines) + "\n"

import argparse
import sys

from .compiler import compile_source
from .disassembler import disassemble
from .errors import MicroVMError
from .serializer import dumps, loads
from .vm import execute


def _positive_int(value: str) -> int:
    try:
        parsed = int(value)
    except ValueError as exc:
        raise argparse.ArgumentTypeError("--step-limit must be a positive integer") from exc
    if parsed <= 0 or isinstance(parsed, bool):
        raise argparse.ArgumentTypeError("--step-limit must be a positive integer")
    return parsed


def _read_text(path: str) -> str:
    try:
        with open(path, "r", encoding="utf-8") as handle:
            return handle.read()
    except OSError as exc:
        raise ValueError(str(exc)) from exc


def _read_bytes(path: str) -> bytes:
    try:
        with open(path, "rb") as handle:
            return handle.read()
    except OSError as exc:
        raise ValueError(str(exc)) from exc


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(prog="microvm", allow_abbrev=False)
    subparsers = parser.add_subparsers(dest="command", required=True)

    run_parser = subparsers.add_parser("run")
    run_parser.add_argument("file")
    run_parser.add_argument("--optimize", action="store_true")
    run_parser.add_argument("--step-limit", type=_positive_int, default=100_000)

    build_parser = subparsers.add_parser("build")
    build_parser.add_argument("source")
    build_parser.add_argument("output")
    build_parser.add_argument("--optimize", action="store_true")

    exec_parser = subparsers.add_parser("exec")
    exec_parser.add_argument("file")
    exec_parser.add_argument("--step-limit", type=_positive_int, default=100_000)

    disasm_parser = subparsers.add_parser("disasm")
    disasm_parser.add_argument("file")

    try:
        args = parser.parse_args(argv)
    except SystemExit as exc:
        return int(exc.code) if isinstance(exc.code, int) else 2

    try:
        if args.command == "run":
            source = _read_text(args.file)
            program = compile_source(source, optimize=args.optimize)
            output = execute(program, step_limit=args.step_limit)
            for line in output:
                print(line)
            return 0
        if args.command == "build":
            source = _read_text(args.source)
            program = compile_source(source, optimize=args.optimize)
            payload = dumps(program)
            with open(args.output, "wb") as handle:
                handle.write(payload)
            return 0
        if args.command == "exec":
            payload = _read_bytes(args.file)
            program = loads(payload)
            output = execute(program, step_limit=args.step_limit)
            for line in output:
                print(line)
            return 0
        if args.command == "disasm":
            payload = _read_bytes(args.file)
            program = loads(payload)
            sys.stdout.write(disassemble(program))
            return 0
    except ValueError as exc:
        print(f"{exc}", file=sys.stderr)
        return 2
    except MicroVMError as exc:
        print(f"{exc}", file=sys.stderr)
        return 3
    except OSError as exc:
        print(f"{exc}", file=sys.stderr)
        return 2
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

