from .compiler import Program
from .errors import SerializationError
from .opcodes import ARG_OPCODE_NAMES, OPCODE_NUMBERS


def _int64_payload(value: int) -> bytes:
    if value < -(1 << 63) or value > (1 << 63) - 1:
        raise SerializationError("INT constant out of range")
    return value.to_bytes(8, byteorder="big", signed=True)


def _encode_constant(value: object) -> tuple[int, bytes]:
    if type(value) is int:
        return 0x01, _int64_payload(value)
    if type(value) is float:
        return 0x02, struct.pack(">d", value)
    if type(value) is str:
        encoded = value.encode("utf-8")
        return 0x03, len(encoded).to_bytes(4, byteorder="big") + encoded
    if type(value) is bool:
        return 0x04, b"\x01" if value else b"\x00"
    raise SerializationError(f"Unsupported constant type: {type(value).__name__}")


def _decode_constant(tag: int, payload: bytes) -> object:
    if tag == 0x01:
        if len(payload) != 8:
            raise SerializationError("Truncated INT payload")
        return int.from_bytes(payload, byteorder="big", signed=True)
    if tag == 0x02:
        if len(payload) != 8:
            raise SerializationError("Truncated FLOAT payload")
        return struct.unpack(">d", payload)[0]
    if tag == 0x03:
        if len(payload) < 4:
            raise SerializationError("Truncated STRING payload")
        length = int.from_bytes(payload[:4], byteorder="big")
        if len(payload) != 4 + length:
            raise SerializationError("Truncated STRING payload")
        return payload[4:].decode("utf-8")
    if tag == 0x04:
        if len(payload) != 1:
            raise SerializationError("Truncated BOOL payload")
        value = payload[0]
        if value not in (0, 1):
            raise SerializationError("BOOL payload must be 0 or 1")
        return value == 1
    raise SerializationError(f"Unknown constant tag: {tag:#x}")


def _encode_name(name: str) -> bytes:
    data = name.encode("utf-8")
    return len(data).to_bytes(2, byteorder="big") + data


def dumps(program: Program) -> bytes:
    body = bytearray()
    body.extend(b"MVM1")
    body.append(1)
    body.extend(len(program.names).to_bytes(2, byteorder="big"))
    for name in program.names:
        body.extend(_encode_name(name))
    body.extend(len(program.constants).to_bytes(2, byteorder="big"))
    for constant in program.constants:
        tag, payload = _encode_constant(constant)
        body.append(tag)
        body.extend(payload)
    body.extend(len(program.instructions).to_bytes(4, byteorder="big"))
    for instr in program.instructions:
        code = OPCODE_NUMBERS[instr.op]
        body.append(code)
